using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.IO;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;

namespace ANetDesktop {
 public sealed partial class Workbench {
  readonly Window window;readonly RuntimeConfig runtime;readonly IClient client;readonly bool testing;
  bool busy,closing; bool environmentBusy {get{return busy;}} string page="Account";
  string receiverPlan="";int receiverPolls;System.Windows.Threading.DispatcherTimer receiverTimer;
  readonly Dictionary<string,FrameworkElement> pages=new Dictionary<string,FrameworkElement>();
  public Workbench(Window w,RuntimeConfig r,IClient c,bool test=false){window=w;runtime=r;client=c;testing=test;
   foreach(string key in new[]{"Account","Agents","Workspace","Services"}){string target=key;pages[key]=Find<FrameworkElement>(key+"Page");Click("Nav"+key,()=>{Navigate(target);return Task.FromResult(true);});}
   Click("RefreshAll",RefreshAll);Click("NextAgents",()=>{Navigate("Agents");return Task.FromResult(true);});Click("Login",Login);Click("Logout",()=>Run(new Dictionary<string,object>{{"action","account.logout"}},ApplyAccount,"正在退出账户…"));
   Click("SaveWorkspace",()=>Run(new Dictionary<string,object>{{"action","config.workspace"},{"path",Find<TextBox>("WorkspacePath").Text.Trim()}},ApplyConfig,"正在保存工作目录…"));
   Click("BrowseWorkspace",()=>{using(var dialog=new System.Windows.Forms.FolderBrowserDialog()){dialog.Description="选择智能体的默认工作目录";dialog.SelectedPath=Find<TextBox>("WorkspacePath").Text;if(dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK)Find<TextBox>("WorkspacePath").Text=dialog.SelectedPath;}return Task.FromResult(true);});
   Click("Doctor",()=>Run(new Dictionary<string,object>{{"action","config.doctor"}},ApplyDiagnostics,"正在检查连接与组件…"));
   Click("ServiceStart",()=>Service("start"));Click("ServiceStop",()=>Service("stop"));
   Click("ReceiverEnable",EnableReceiver);Click("ReceiverRefresh",RefreshReceiver);
   if(!test)InitializeUpdates();else{Find<TextBlock>("UpdateState").Text="测试预览 · 不检查在线更新";Find<Button>("UpdateApply").IsEnabled=false;}
   window.Loaded+=async(s,e)=>{Navigate("Account");await RefreshAll();};window.Closing+=OnClosing;Navigate("Account");
  }
  T Find<T>(string name) where T:class{var result=window.FindName(name)as T;if(result==null)throw new InvalidDataException("missing_control:"+name);return result;}
  void Click(string name,Func<Task<bool>> action){Find<Button>(name).Click+=async(s,e)=>await action();}
  static Brush Brush(string color){return (Brush)new BrushConverter().ConvertFromString(color);}
  public void Navigate(string name){page=name;foreach(var p in pages)p.Value.Visibility=p.Key==name?Visibility.Visible:Visibility.Collapsed;foreach(string key in pages.Keys){var b=Find<Button>("Nav"+key);b.Background=Brush(key==name?"#24202A":"#00FFFFFF");b.Foreground=Brush(key==name?"#FF9154":"#A7B0C0");}
   string title=name=="Account"?"连接你的设备":name=="Agents"?"连接智能体":name=="Workspace"?"工作目录":"服务与更新";
   string subtitle=name=="Account"?"登录 ANet，完成这台电脑的网络连接。":name=="Agents"?"接入后，回到你熟悉的软件里使用 ANet。":name=="Workspace"?"为这台电脑选择一个默认工作位置。":"查看连接状态，检查问题并保持版本更新。";
   Find<TextBlock>("PageTitle").Text=title;Find<TextBlock>("PageSubtitle").Text=subtitle;
  }
  void Notice(string text,bool attention=false){Find<TextBlock>("NoticeText").Text=text;Find<TextBlock>("NoticeText").Foreground=Brush(attention?"#FFB547":"#A7B0C0");}
  void SetBusy(bool value){busy=value;Find<FrameworkElement>("PageContent").IsEnabled=!value;Find<Button>("RefreshAll").IsEnabled=!value;Find<ProgressBar>("BusyIndicator").Visibility=value?Visibility.Visible:Visibility.Collapsed;}
  async Task<bool> Run(Dictionary<string,object> request,Action<Dictionary<string,object>> apply,string progress){if(busy)return false;SetBusy(true);Notice(progress);try{var result=await Task.Run(()=>client.Exchange(request));apply(result);string state=Data.Text(result,"state");bool error=state=="error"||state=="failed"||state=="needs_attention"||(result.ContainsKey("ok")&&!Data.Flag(result,"ok"));string message=Data.Text(result,"message");if(message=="")message=Data.Text(result,"detail_check");if(message=="")message=Data.Text(result,"detail");Notice(message==""?(error?"操作未完成，请查看状态后重试。":"设置已更新。可回到智能体软件继续使用。"):message,error);return !error;}catch{Notice("暂时无法完成操作。请检查服务状态，或运行连接检查。",true);return false;}finally{request.Remove("password");SetBusy(false);}}
  public async Task<bool> RefreshAll(){if(busy)return false;bool a=await Run(new Dictionary<string,object>{{"action","account.status"}},ApplyAccount,"正在检查账户连接…");bool b=await Run(new Dictionary<string,object>{{"action","config.status"}},ApplyConfig,"正在检查智能体与服务…");await RefreshReceiver();if(a&&b)Notice("状态已更新。");else if(!a)Notice("设备尚未连接。请登录账户，或到「服务与更新」检查。",true);return a&&b;}
  Task<bool> RefreshReceiver(){return Run(new Dictionary<string,object>{{"action","config.receiver"},{"operation","status"}},ApplyReceiver,"正在检查接收协作设置…");}
  async Task<bool> PrepareReceiver(string harness,string name){Find<PasswordBox>("ReceiverPassword").Clear();receiverPlan="";Find<FrameworkElement>("ReceiverPanel").Visibility=Visibility.Collapsed;Find<TextBlock>("ReceiverSelection").Text="使用 "+name+" 接收协作";bool ok=await Run(new Dictionary<string,object>{{"action","config.receiver"},{"operation","prepare"},{"harness",harness}},ApplyReceiver,"正在检查接收协作的条件…");if(receiverPlan!=""){window.UpdateLayout();Find<Button>("ReceiverEnable").BringIntoView();Find<PasswordBox>("ReceiverPassword").Focus();}return ok;}
  Task<bool> EnableReceiver(){string password=Find<PasswordBox>("ReceiverPassword").Password;Find<PasswordBox>("ReceiverPassword").Clear();if(receiverPlan==""||password==""){Notice("请先选择执行器，并输入门户密码。",true);return Task.FromResult(false);}return Run(new Dictionary<string,object>{{"action","account.enable_receiver"},{"plan_id",receiverPlan},{"confirm",true},{"username",Find<TextBox>("Username").Text.Trim()},{"password",password}},ApplyReceiver,"正在开启接收协作并启动自检…");}
  void ApplyReceiver(Dictionary<string,object>d){var r=Data.Child(d,"receiver");if(r==null){Find<TextBlock>("ReceiverState").Foreground=Brush("#A7B0C0");string message=Data.Text(d,"message");if(message!="")Find<TextBlock>("ReceiverState").Text=message;return;}string state=Data.Text(r,"state"),detail=Data.Text(r,"detail");Find<TextBlock>("ReceiverState").Text=detail;Find<TextBlock>("ReceiverState").Foreground=Brush(state=="ready"&&Data.Flag(r,"ready")?"#38E8C6":"#A7B0C0");if(state=="prepared"){receiverPlan=Data.Text(d,"plan_id");Find<FrameworkElement>("ReceiverPanel").Visibility=Visibility.Visible;}else if(state=="testing"||Data.Flag(r,"ready")){receiverPlan="";Find<FrameworkElement>("ReceiverPanel").Visibility=Visibility.Collapsed;}if(state=="testing"&&!testing&&receiverTimer==null){receiverPolls=0;receiverTimer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromSeconds(5)};receiverTimer.Tick+=async(s,e)=>{if(closing||++receiverPolls>60){receiverTimer.Stop();receiverTimer=null;return;}if(!busy)await RefreshReceiver();};receiverTimer.Start();}else if(state!="testing"&&receiverTimer!=null){receiverTimer.Stop();receiverTimer=null;}}
  async Task<bool> Login(){string url=Find<TextBox>("PortalUrl").Text.Trim(),user=Find<TextBox>("Username").Text.Trim(),password=Find<PasswordBox>("Password").Password;Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.Scheme!="https"){Notice("请输入以 https:// 开头的门户地址。",true);return false;}if(user==""||password==""){Notice("请输入账户和密码。",true);return false;}var request=new Dictionary<string,object>{{"action","account.login"},{"url",url},{"portal",url},{"username",user},{"password",password}};Find<PasswordBox>("Password").Clear();return await Run(request,ApplyAccount,"正在登录并连接这台电脑…");}
  async Task<bool> Service(string op){bool ok=await Run(new Dictionary<string,object>{{"action","config.service"},{"service_id","node"},{"operation",op}},ApplyConfig,op=="start"?"正在启动连接服务…":"正在停止连接服务…");if(ok)await RefreshAll();return ok;}
  void ApplyAccount(Dictionary<string,object>d){var a=Data.Child(d,"account");var c=Data.Child(d,"connection");string state=Data.Text(c,"state");bool ready=Data.Text(d,"state")=="ready"&&Data.Flag(c,"portal_paired")&&Data.Flag(c,"hub_connected");Find<TextBlock>("ConnectionState").Text=ready?"● 设备已连接":"○ 设备尚未连接";Find<TextBlock>("ConnectionState").Foreground=Brush(ready?"#38E8C6":"#FFB547");Find<TextBlock>("ConnectionDetail").Text=Data.Text(c,"detail");Find<TextBlock>("SidebarStatus").Text=ready?"设备在线":"等待连接";Find<TextBlock>("SidebarStatus").Foreground=Brush(ready?"#38E8C6":"#A7B0C0");string url=Data.Text(a,"url"),user=Data.Text(a,"username");if(url!="")Find<TextBox>("PortalUrl").Text=url;if(user!=""||Data.Text(a,"state")=="signed_out")Find<TextBox>("Username").Text=user;Find<TextBlock>("AccountSummary").Text=user==""?"使用门户账户登录即可连接设备。":"当前账户  "+user;Find<Button>("Logout").Visibility=user==""?Visibility.Collapsed:Visibility.Visible;}
  void ApplyConfig(Dictionary<string,object>d){object raw;if(d.TryGetValue("workspace",out raw)){string path=raw is string?(string)raw:Data.Text(Data.Map(raw),"path");if(path!="")Find<TextBox>("WorkspacePath").Text=path;}
   if(d.ContainsKey("agents")){var list=Find<StackPanel>("AgentList");list.Children.Clear();foreach(var row in Data.Rows(d,"agents"))list.Children.Add(AgentCard(row));}
   if(d.ContainsKey("services")){var list=Find<StackPanel>("ServiceList");list.Children.Clear();foreach(var row in Data.Rows(d,"services")){string state=Data.Text(row,"state"),name=Data.Text(row,"name");if(name=="")name=Data.Text(row,"id");var p=new StackPanel{Margin=new Thickness(0,0,0,16)};p.Children.Add(Text(name+"  ·  "+State(state),15,"#E9EDF4"));p.Children.Add(Text(Data.Text(row,"detail"),12,"#A7B0C0"));list.Children.Add(p);}}
   if(d.ContainsKey("checks"))ApplyDiagnostics(d);
  }
  FrameworkElement AgentCard(Dictionary<string,object>row){string id=Data.Text(row,"id"),name=Data.Text(row,"name");if(name=="")name=id;var g=new Grid();g.ColumnDefinitions.Add(new ColumnDefinition());g.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var p=new StackPanel{Margin=new Thickness(0,0,22,0)};p.Children.Add(Text(name,18,"#E9EDF4"));bool configured=Data.Flag(row,"configured");p.Children.Add(Text(configured?"● 已配置 ANet 接入":State(Data.Text(row,"state")),12,configured?"#38E8C6":"#FFB547"));p.Children.Add(Text(Data.Text(row,"detail"),12,"#A7B0C0"));g.Children.Add(p);var b=new Button{Content=configured?"重新配置":"连接 ANet",VerticalAlignment=VerticalAlignment.Center,MinWidth=106};System.Windows.Automation.AutomationProperties.SetName(b,name+" 连接 ANet");b.Click+=async(s,e)=>{if(await Run(new Dictionary<string,object>{{"action","config.configure_agent"},{"harness",id}},ApplyConfig,"正在为 "+name+" 配置 ANet…"))await RefreshAll();};var actions=new StackPanel{VerticalAlignment=VerticalAlignment.Center};actions.Children.Add(b);var verify=new Button{Content="检测连接",Margin=new Thickness(0,8,0,0),MinWidth=106,IsEnabled=configured};System.Windows.Automation.AutomationProperties.SetName(verify,name+" 检测连接");verify.Click+=async(s,e)=>await Run(new Dictionary<string,object>{{"action","config.verify"},{"harness",id}},value=>{string detail=Data.Text(value,"detail_check");if(detail!="")Notice(detail);},"正在检测 ANet 工具连接…");actions.Children.Add(verify);var receive=new Button{Content="设为执行器",Margin=new Thickness(0,8,0,0),MinWidth=106};System.Windows.Automation.AutomationProperties.SetName(receive,name+" 设为接收协作执行器");receive.Click+=async(s,e)=>await PrepareReceiver(id,name);actions.Children.Add(receive);Grid.SetColumn(actions,1);g.Children.Add(actions);return new Border{Style=(Style)window.FindResource("Card"),Child=g,Margin=new Thickness(0,0,0,14)};}
  static TextBlock Text(string text,double size,string color){return new TextBlock{Text=text,FontSize=size,Foreground=Brush(color),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,4)};}
  static string State(string s){switch(s){case "ready":case "running":case "connected":return "已连接";case "configured":return "已配置";case "unconfigured":return "尚未连接";case "disabled":return "已停用";case "conflict":return "需要检查配置";case "update_available":return "可更新配置";case "stopped":return "已停止";case "missing":case "not_installed":return "尚未安装";case "needs_login":return "请在软件中登录";case "needs_setup":case "not_configured":return "等待配置";case "error":case "failed":return "需要处理";default:return "等待检查";}}
  void ApplyDiagnostics(Dictionary<string,object>d){var lines=new List<string>();foreach(var row in Data.Rows(d,"checks")){string label=Data.Text(row,"name");if(label=="")label=Data.Text(row,"id");lines.Add(label+" · "+State(Data.Text(row,"state"))+"\n"+Data.Text(row,"detail"));}if(lines.Count==0){string message=Data.Text(d,"message");if(message=="")message=Data.Text(d,"detail");lines.Add(message==""?"检查已结束，请查看上方连接状态。":message);}Find<TextBlock>("Diagnostics").Text=String.Join("\n\n",lines);}
  async void OnClosing(object sender,CancelEventArgs e){if(closing)return;e.Cancel=true;if(busy||environmentBusy){Notice("当前设置正在保存，完成后即可关闭。",true);return;}if(!testing)await ApplyPreparedUpdate();closing=true;await window.Dispatcher.InvokeAsync(new Action(()=>window.Close()));}
 }
 public static class Program {
  [STAThread]public static int Main(string[]args){try{string package=AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar);string path=Path.Combine(package,"install","runtime.json");if(args.Length==2&&args[0]=="--runtime")path=Path.GetFullPath(args[1]);else if(args.Length!=0)throw new ArgumentException("invalid_arguments");else if(!File.Exists(path)){package=Directory.GetParent(package).FullName;path=Path.Combine(package,"install","runtime.json");}var runtime=RuntimeConfig.Load(path,package);var app=new Application();Window w;using(var stream=typeof(Program).Assembly.GetManifestResourceStream("ANetDesktop.MainWindow.xaml"))w=(Window)XamlReader.Load(stream);var view=new Workbench(w,runtime,new ConfigClient(runtime));app.Run(w);GC.KeepAlive(view);return 0;}catch{MessageBox.Show("ANet 的安装组件暂时不可用。请重新运行安装程序进行修复。","ANet · 需要设置",MessageBoxButton.OK,MessageBoxImage.Information);return 1;}}
 }
}
